<?php $activeMenu='router';$routerView='log';require_once __DIR__.'/../includes/sidebar.php'; ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Log Router - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css"><link rel="stylesheet" href="../assets/css/common.css"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><style>body{margin:0}.page{margin-left:220px;padding:32px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.title{font-size:28px;font-weight:700}.sub,.muted{color:#66758d}.actions{display:flex;gap:10px}.btn{border:1px solid #d7e0ec;background:#fff;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.primary{background:#087cff;color:#fff;border-color:#087cff}.input{border:1px solid #d7e0ec;border-radius:8px;padding:10px 12px;min-width:230px}.card{background:#fff;border:1px solid #dce4ef;border-radius:14px;overflow:hidden}.bar{padding:16px 20px;border-bottom:1px solid #e4e9f0;display:flex;justify-content:space-between}.wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px 14px;border-bottom:1px solid #edf1f6;text-align:left;font-size:12px}th{font-size:10px;text-transform:uppercase;color:#61718a;background:#f7f9fc}.topic{font-weight:600}.message{min-width:380px}.notice{padding:18px;color:#66758d}@media(max-width:800px){.page{margin-left:0;padding:20px}.head{align-items:flex-start;flex-direction:column;gap:12px}.actions{width:100%;flex-wrap:wrap}.input{min-width:180px;flex:1}.message{min-width:250px}}</style></head><body><main class="page"><div class="head"><div><div class="title">Log Router</div><div class="sub">Log sistem MikroTik terbaru, maksimal 300 baris.</div></div><div class="actions"><input class="input" id="filter" placeholder="Filter topic / pesan..."><button class="btn primary" id="refresh">↻ Refresh</button></div></div><div class="card"><div class="bar"><strong id="router">Router</strong><span class="muted" id="updated">Belum diperbarui</span></div><div class="wrap"><table><thead><tr><th>Tanggal</th><th>Waktu</th><th>Topic</th><th>Pesan</th></tr></thead><tbody id="rows"><tr><td colspan="4" class="notice">Memuat log...</td></tr></tbody></table></div></div></main><script>const rows=document.getElementById('rows'),filter=document.getElementById('filter'),router=document.getElementById('router'),updated=document.getElementById('updated'),refresh=document.getElementById('refresh');let logs=[];const esc=v=>String(v??'-').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));function render(){const q=filter.value.toLowerCase().trim(),a=logs.filter(x=>(x.topics+' '+x.message).toLowerCase().includes(q));rows.innerHTML=a.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.time)}</td><td class="topic">${esc(x.topics)}</td><td class="message">${esc(x.message)}</td></tr>`).join('')||'<tr><td colspan="4" class="notice">Tidak ada log yang sesuai.</td></tr>'}async function load(){refresh.disabled=true;try{const r=await fetch('../api/router_log.php?nocache='+Date.now(),{cache:'no-store'}),d=await r.json();if(d.status!=='online')throw Error(d.message||'Router offline');logs=d.logs||[];router.textContent=d.router||'Router';render()}catch(e){rows.innerHTML='<tr><td colspan="4" class="notice">Gagal mengambil log: '+esc(e.message)+'</td></tr>'}finally{updated.textContent='Update '+new Date().toLocaleTimeString('id-ID');refresh.disabled=false}}filter.oninput=render;refresh.onclick=load;load();setInterval(load,15000)</script><script src="../assets/js/app.js?v=6"></script></body></html>